import numpy as np
from collections import Counter as C
def quadinfo(gi):
    h,w=len(gi),len(gi[0]); qh,qw=h//2,w//2
    quads={'TL':gi[:qh][:qw],'TR':gi[:qh][qw:],'BL':gi[qh:][:qw],'BR':gi[qh:][qw:]}
    res=[]
    for qn,gq in quads.items():
        cnt=C(x for r in gq for x in r)
        res.append((qn,cnt.most_common()))
    return res
