# Rule: out = color present in exactly one quad (unique color) if exists and unique; if several unique colors, pick the one from the quietest quad (min noise count, tie -> lower idx); else the most common color among the four.
def f(gi):
    qs=quads(gi); H,W=len(qs[0]),len(qs[0][0])
    nb=[sum(n for c,n in C(x for r in q for x in r).items() if c!=bgsq) for m,q,bgsq in zip(range(4),qs,[C(x for r in qq for x in r).most_common(1)[0][0] for qq in qs])]
    go=[]
    for i in range(H):
        row=[]
        for j in range(W):
            uq={}  # color -> list of quad indices having it
            uniq={}
            for m in range(4):
                v=qs[m][i][j]
                if v not in uq: uq[v]=[m]
                else: uq[v].append(m)
            # candidates: colors in exactly one quad
            cand={c:n for c,n in uq.items() if len(n)==1}
            if len(cand)==1: row.append(list(cand.values())[0])
            elif len(cand)>1:
                best=None
                for c,m in cand.items():
                    if best is None or nb[m]<nb[best[0]]: best=(m,c)
                row.append(best[1])
            else:
                mn=min(C([qs[m][i][j] for m in range(4)]).values())
                row.append(min(c for c,n in C([qs[m][i][j] for m in range(4)]).items() if n==mn))
        go.append(row)
    return go
